using MultiFunPlayer.OutputTarget.Tracking;
using MultiFunPlayer.OutputTarget.TCodeBuffered;
using System.Buffers.Binary;
using System.Threading.Channels;

namespace MultiFunPlayer.TCode.Tests;

public class TrackingTests
{
    [Fact]
    public void ProductionFirmwareWireAndAsynchronousEncodersRecoverKnownTracking()
    {
        // Generated by CTW test/tracking_native using production CAD IK and
        // production packet encoding. Seven feedback ages deliberately differ.
        var analysis = new TrackingAnalysis();
        var lines = File.ReadAllLines(Path.Combine(AppContext.BaseDirectory, "TestData", "tracking-cad.frames"));
        Assert.Equal(401, lines.Length);
        foreach (var line in lines)
        {
            Assert.True(TrackingPacket.TryDecode(line, out var packet, out var error), error);
            analysis.Add(packet, packet.TimeMicroseconds / 1e6, 10, 2);
        }
        var snapshot = analysis.Snapshot();
        Assert.InRange(snapshot.Quality.SolveValidPercent.Value, 99, 100);
        Assert.InRange(snapshot.Quality.MaxResidualMm.Value, 0, .05);
        Assert.InRange(snapshot.Quality.EffectiveHz.Value, 49.9, 50.1);
        Assert.Equal(0, snapshot.Quality.Missing);
        var stroke = snapshot.Axes[0].Statistics;
        Assert.InRange(stroke.DelayMs.Value.Value, 56, 64);
        Assert.InRange(stroke.AmplitudePercent.Value.Value, 88.5, 91.5);
        Assert.InRange(stroke.Rms.Value.Value, 2, 4);
        var twist = snapshot.Axes[3].Statistics;
        Assert.InRange(twist.DelayMs.Value.Value, 37, 43);
        Assert.InRange(twist.AmplitudePercent.Value.Value, 108, 112);
        Assert.NotNull(twist.Overshoot.Value);
        Assert.InRange(twist.Overshoot.Value.Value, .6, 1.1);
        Assert.InRange(twist.PhaseDegrees.Value.Value, 12, 20);
    }

    [Fact]
    public async Task ContinuouslyDeliveredOldSnapshotsAreNotPresentedAsLive()
    {
        using var monitor = new TrackingMonitor();
        monitor.Accept(Packet(1, 2), deviceNowUs: 3000000, clockUncertaintyMs: 2);
        await Task.Delay(150);
        Assert.False(monitor.IsLive);
        Assert.Equal(1000, monitor.Snapshot.Quality.DeliveryAgeMs.Value);
    }

    [Fact]
    public void CadClosureRecoversIndependentDesktopReferencePose()
    {
        // Desktop sr6_simu gold vector, also used by firmware test_cad_8108_ik.
        double[] q = [.0327139160, -.1114087164, -.1550779168, -.2433798320, -.1931007427, -.0577205426];
        var result = CadForwardKinematics.Solve(q);
        Assert.True(result.Valid);
        Assert.InRange(result.MaxResidualMm, 0, .0001);
        Assert.InRange(result.Receiver[0], 7.999, 8.001);
        Assert.InRange(result.Receiver[1], 11.999, 12.001);
        Assert.InRange(result.Receiver[2], -5.001, -4.999);
        Assert.InRange(result.Receiver[3], .05999, .06001);
        Assert.InRange(result.Receiver[4], -.08001, -.07999);
        var target = CadForwardKinematics.TipAxes(result.Receiver, .2, 220);
        var recovered = CadForwardKinematics.SeedFromTip(target, 220);
        for (var i = 0; i < 5; i++) Assert.Equal(result.Receiver[i], recovered[i], 8);
    }

    [Fact]
    public void CadClosureRejectsNonclosingEncoderSetAndNan()
    {
        Assert.False(CadForwardKinematics.Solve([.9, -.1114, -.1551, -.2434, -.1931, -.0577]).Valid);
        Assert.False(CadForwardKinematics.Solve([double.NaN, 0, 0, 0, 0, 0]).Valid);
    }

    [Theory]
    [InlineData(.06, .9)]
    [InlineData(.12, 1.1)]
    [InlineData(-.04, 1)]
    public void WindowSeparatesLagAmplitudeAndUnshiftedError(double lag, double gain)
    {
        const double frequency = 1.3;
        var points = Enumerable.Range(0, 401).Select(i => {
            var time = i * .02;
            return new TrackingPoint(time, 10 * Math.Sin(2 * Math.PI * frequency * time),
                gain * 10 * Math.Sin(2 * Math.PI * frequency * (time - lag)));
        }).ToArray();
        var stats = TrackingStatistics.Analyze(points, 0, 6, 8);
        Assert.NotNull(stats.DelayMs.Value);
        Assert.InRange(stats.DelayMs.Value.Value, lag * 1000 - 3, lag * 1000 + 3);
        Assert.InRange(stats.AmplitudePercent.Value.Value, gain * 100 - 1, gain * 100 + 1);
        Assert.InRange(stats.FrequencyHz.Value.Value, frequency - .03, frequency + .03);
        Assert.InRange(stats.PhaseDegrees.Value.Value, lag * frequency * 360 - 3, lag * frequency * 360 + 3);
        Assert.InRange(stats.Rms.Value.Value, 1, 9); // a perfect lag fit must not erase real tracking error
        Assert.NotNull(stats.Overshoot.Value);
        if (gain > 1) Assert.InRange(stats.Overshoot.Value.Value, .8, 1.2);
        else Assert.InRange(stats.Overshoot.Value.Value, 0, .05);
    }

    [Fact]
    public void StablePeriodicPhaseSurvivesWholeCycleDelayAmbiguity()
    {
        var points = Enumerable.Range(0, 401).Select(i => {
            var t = i * .02;
            return new TrackingPoint(t, 10 * Math.Sin(2 * Math.PI * 3 * t), 9 * Math.Sin(2 * Math.PI * 3 * (t - .12)));
        }).ToArray();
        var result = TrackingStatistics.Analyze(points, 0, 6, 8);
        Assert.Null(result.DelayMs.Value);
        Assert.InRange(result.PhaseDegrees.Value.Value, 126, 133);
        Assert.InRange(result.AmplitudePercent.Value.Value, 89, 91);
    }

    [Fact]
    public void StaticAndUniformRampNeverClaimZeroDelayOrPerfectAmplitude()
    {
        foreach (var ramp in new[] { false, true })
        {
            var points = Enumerable.Range(0, 301).Select(i => new TrackingPoint(i * .02, ramp ? i * .1 : 12, ramp ? i * .1 - 2 : 10)).ToArray();
            var stats = TrackingStatistics.Analyze(points, 0, 4, 6);
            Assert.Equal(-2, stats.Error.Value.Value, 8);
            Assert.Equal(2, stats.Rms.Value.Value, 8);
            Assert.Equal(2, stats.P95.Value.Value, 8);
            Assert.Null(stats.DelayMs.Value);
            Assert.Null(stats.AmplitudePercent.Value);
            Assert.Null(stats.PhaseDegrees.Value);
            Assert.Null(stats.Overshoot.Value);
        }
    }

    [Fact]
    public void StepArrivalReportsOvershootWithoutInventingAPeriod()
    {
        var points = Enumerable.Range(0, 151).Select(i => {
            var t = i * .02;
            var actual = t < 1 ? 0 : 10 + Math.Exp(-(t - 1) * 5) * Math.Sin((t - 1) * 20);
            return new TrackingPoint(t, t < 1 ? 0 : 10, actual);
        }).ToArray();
        var result = TrackingStatistics.Analyze(points, 0, 4, 3);
        Assert.InRange(result.Overshoot.Value.Value, .6, .8);
        Assert.Null(result.PhaseDegrees.Value);
    }

    [Fact]
    public void P95DoesNotHideOutliersInRmsAndTimeGapsDisableFit()
    {
        var points = Enumerable.Range(0, 100).Select(i => new TrackingPoint(i * .02, 0, i == 99 ? 10 : 1)).ToArray();
        var stats = TrackingStatistics.Analyze(points, 0, 4, 2);
        Assert.Equal(1, stats.P95.Value.Value);
        Assert.InRange(stats.Rms.Value.Value, 1.4, 1.42);
        var hole = Enumerable.Range(0, 400).Select(i => new TrackingPoint(i * .02, i % 3 == 0 ? double.NaN : Math.Sin(i * .04), i % 3 == 0 ? double.NaN : Math.Sin(i * .04))).ToArray();
        var incomplete = TrackingStatistics.Analyze(hole, 0, 4, 8);
        Assert.Null(incomplete.DelayMs.Value);
    }

    [Fact]
    public void PacketUsesAsciiSafeCrcFrameAndRejectsCorruptionOrModelMismatch()
    {
        var source = Packet(1, 2);
        var wire = Encode(source);
        Assert.Equal(208, wire.Length);
        Assert.True(TrackingPacket.TryDecode(wire, out var decoded, out _));
        Assert.Equal(source.TimeMicroseconds, decoded.TimeMicroseconds);
        Assert.Equal(source.Target, decoded.Target);
        Assert.Equal(source.Feedback, decoded.Feedback);
        var corrupted = wire.ToCharArray(); corrupted[20] = corrupted[20] == 'A' ? 'B' : 'A';
        Assert.False(TrackingPacket.TryDecode(new string(corrupted), out _, out _));
        var raw = Convert.FromBase64String(wire[TrackingPacket.Prefix.Length..].Trim());
        raw[6] = 2;
        BinaryPrimitives.WriteUInt32LittleEndian(raw.AsSpan(144), TrackingPacket.Crc32(raw.AsSpan(0, 144)));
        Assert.False(TrackingPacket.TryDecode(TrackingPacket.Prefix + Convert.ToBase64String(raw), out _, out var error));
        Assert.Contains("模型版本", error);
    }

    [Fact]
    public void IndependentR0WorksWithoutParallelMotorsAndCountsMissingPackets()
    {
        var analysis = new TrackingAnalysis();
        for (uint i = 1; i <= 302; i++)
        {
            if (i == 100) continue;
            var p = Packet(i, 2 + i * .02) with { MotorMask = 64, Axes = 8, FeedbackValid = 64, CommandValid = 64 };
            p.Target[3] = 10; p.Command[6] = 10 * Math.PI / 180; p.Feedback[6] = 8 * Math.PI / 180;
            analysis.Add(p, i * .02);
        }
        var view = analysis.Snapshot();
        Assert.Equal(1, view.Quality.Missing);
        Assert.InRange(view.Axes[3].Statistics.Rms.Value.Value, 1.999, 2.001);
        Assert.Null(view.Axes[0].Statistics.Rms.Value);
        var last = Packet(303, 8.06) with { MotorMask = 64, FeedbackValid = 0, CommandValid = 64 };
        analysis.Add(last, 8.06);
        Assert.Null(analysis.Snapshot().Axes[3].Statistics.Error.Value);
    }

    [Fact]
    public async Task CorruptTelemetryAndSubscriptionAckCannotConsumePlaybackAck()
    {
        var received = Channel.CreateUnbounded<string>();
        using var monitor = new TrackingMonitor();
        var operations = new List<ulong>();
        await using var client = new TCodeBufferedClient((wire, _) => {
            Assert.True(TCodeBufferedProtocol.TryDecode(wire, out var f));
            lock (operations) operations.Add(f[0]);
            var reply = f[0] == 12
                ? new ulong[] { 106, f[1], 99, 0, 0, 0, 1, f[4], f[5], 1 }
                : new ulong[] { 100, f[1], 99, 0, 0, 0, 1000000, 0, 512, 512, 512, 512, 512, 512, 512, 8000000, 8000000, 8000000, 0, 8000000, 8000000, 0 };
            received.Writer.TryWrite("!TRK1,broken\n" + Encode(Packet(1, 2)) + TCodeBufferedProtocol.Encode(reply));
            return Task.CompletedTask;
        }, async token => await received.Reader.ReadAsync(token), tracking: monitor);
        await client.SendAsync(0, CancellationToken.None);
        client.StartTracking();
        var ack = await client.SendAsync(0, CancellationToken.None).WaitAsync(TimeSpan.FromSeconds(2));
        Assert.Equal(100UL, ack[0]);
        await Task.Delay(150);
        Assert.True(monitor.Snapshot.Quality.Corrupt > 0);
        lock (operations) Assert.Contains(12UL, operations);
    }

    internal static TrackingPacket Packet(uint sequence, double time) => new(99, 0, sequence, (ulong)Math.Round(time * 1e6), 127,
        TrackingFlags.Running | TrackingFlags.Reachable | TrackingFlags.TargetValid | TrackingFlags.Mit, 127, 127, 63,
        new double[6], new double[7], new double[7], new ushort[7], new ushort[7], 0, 0, 20);

    internal static string Encode(TrackingPacket p)
    {
        var bytes = new byte[148];
        bytes[0] = 1; bytes[1] = p.MotorMask; bytes[2] = (byte)p.Flags; bytes[3] = p.FeedbackValid; bytes[4] = p.CommandValid; bytes[5] = p.Axes;
        BinaryPrimitives.WriteUInt16LittleEndian(bytes.AsSpan(6), 1);
        BinaryPrimitives.WriteUInt32LittleEndian(bytes.AsSpan(8), p.Boot); BinaryPrimitives.WriteUInt32LittleEndian(bytes.AsSpan(12), p.Session);
        BinaryPrimitives.WriteUInt32LittleEndian(bytes.AsSpan(16), p.Sequence); BinaryPrimitives.WriteUInt64LittleEndian(bytes.AsSpan(20), p.TimeMicroseconds);
        for (var i = 0; i < 6; i++) Write(28 + i * 4, p.Target[i]);
        for (var i = 0; i < 7; i++) { Write(52 + i * 4, p.Command[i]); Write(80 + i * 4, p.Feedback[i]);
            BinaryPrimitives.WriteUInt16LittleEndian(bytes.AsSpan(108 + i * 2), p.CommandAgeMs[i]);
            BinaryPrimitives.WriteUInt16LittleEndian(bytes.AsSpan(122 + i * 2), p.FeedbackAgeMs[i]); }
        Write(136, p.StickMm); BinaryPrimitives.WriteUInt16LittleEndian(bytes.AsSpan(140), p.TargetAgeMs);
        BinaryPrimitives.WriteUInt16LittleEndian(bytes.AsSpan(142), p.PeriodMs);
        BinaryPrimitives.WriteUInt32LittleEndian(bytes.AsSpan(144), TrackingPacket.Crc32(bytes.AsSpan(0, 144)));
        return TrackingPacket.Prefix + Convert.ToBase64String(bytes) + "\r\n";
        void Write(int offset, double value) => BinaryPrimitives.WriteInt32LittleEndian(bytes.AsSpan(offset), BitConverter.SingleToInt32Bits((float)value));
    }
}
